CREATE TABLE IF NOT EXISTS ai_agents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'copilot',language TEXT NOT NULL DEFAULT 'en',tone TEXT NOT NULL DEFAULT 'professional',system_policy TEXT,escalation_rules JSONB NOT NULL DEFAULT '{}'::jsonb,allowed_tools JSONB NOT NULL DEFAULT '[]'::jsonb,is_active BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS handoffs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE,lead_id UUID REFERENCES leads(id) ON DELETE SET NULL,requested_by TEXT NOT NULL DEFAULT 'ai_agent',assigned_user_id UUID REFERENCES users(id) ON DELETE SET NULL,reason TEXT NOT NULL,summary TEXT,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS agents_tenant_idx ON ai_agents(tenant_id,is_active);CREATE INDEX IF NOT EXISTS handoffs_tenant_idx ON handoffs(tenant_id,status,priority,created_at DESC);